// Parity checks of the Irodori-TTS v4-Large text layer — the Gemma BPE tokenizer of T5Gemma 2
// behind Irodori's own normalization and back end (src/irodori/text/{asset,gemma-tokenizer,
// text-tokenizer}.ts) — and of the choice of tokenizer by the asset's format.
//
// The fixture `irodori-text/v4-large-parity.json` is generated by the recipe
// (tools/export-recipes/irodori/tokenizer_ref.py, the Gemma kind). Its id lists were measured with
// upstream's `normalize_text` and `tokenizers` / `transformers` (`PretrainedTextTokenizer` for the
// padded and packed forms). It holds
//  - `{raw, normalized, ids}` encode cases (byte fallback, added and special tokens typed in the
//    text, newlines, spaces)
//  - `batch_encode`'s final form at max_text_len (one case truncates) and at max_caption_len
//  - caption cases through the caption path (strip only) and the text path (normalize), one beyond
//    max_text_len and one cut at max_caption_len
//  - the Gemma asset **subset** those cases need, and the BOS / pad ids upstream's wrapper uses
// The normalize golden and the NFKC table are tokenizer-independent and are checked against
// `parity.json` by `irodori_text_test.ts`.
//
// It depends on neither real assets nor a GPU, so it always runs.

import { readTextFile } from "@karume/test-support/fs";
import { describe, it } from "vite-plus/test";
import { assert, assertEquals, assertInstanceOf, assertThrows } from "@std/assert";
import { ModelInputError } from "../src/errors.ts";
import type { GemmaTokenizerAssets } from "../src/gemma/text/asset.ts";
import { packCaptionIds, packIds } from "../src/irodori/host/pack.ts";
import { resolveSplitRareTokens } from "../src/irodori/pipeline.ts";
import { parseIrodoriTextTokenizer } from "../src/irodori/text/asset.ts";
import { IrodoriGemmaTokenizer } from "../src/irodori/text/gemma-tokenizer.ts";
import { normalizeText } from "../src/irodori/text/normalize.ts";
import { encodePaddedIds } from "../src/irodori/text/text-tokenizer.ts";
import { IrodoriTokenizer } from "../src/irodori/text/tokenizer.ts";
import { createBpeModel } from "../src/text/bpe.ts";

type EncodeCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
  readonly ids: number[];
};

type BatchCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
  readonly maxLength: number;
  readonly idsPadded: number[];
  readonly mask: boolean[];
};

type CaptionCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly stripped: string;
  readonly normalized: string;
  readonly maxLength: number;
  readonly idsPacked: number[];
  readonly normalizedIdsPacked: number[];
  readonly normalizeSensitive: boolean;
};

type Fixture = {
  readonly spec: {
    readonly normalizer: string;
    readonly preTokenizer: string;
    readonly decoder: string;
    readonly postProcessor: "none" | "bos-eos" | "bos";
  };
  readonly conditioning: { readonly bosId: number; readonly padId: number };
  readonly asset: {
    readonly vocab: [number, string][];
    readonly merges: [number, number, number][];
    readonly byteIds: number[];
    readonly addedTokens: [string, number][];
    readonly specialIds: number[];
    readonly unkId: number;
    readonly bosId: number;
    readonly eosId: number;
  };
  readonly encode: {
    readonly cases: EncodeCase[];
    readonly batch: BatchCase[];
    readonly caption: CaptionCase[];
  };
};

const FIXTURE_PATH = new URL("./fixtures/irodori-text/v4-large-parity.json", import.meta.url);
const fixture = JSON.parse(await readTextFile(FIXTURE_PATH)) as Fixture;

/**
 * Builds the Gemma asset tables directly from the fixture's subset (the same construction as
 * `gemma4_tokenizer_test.ts` — the JSON reader's checks are covered there and by the format tests
 * below).
 */
const assets: GemmaTokenizerAssets = {
  spec: { postProcessor: fixture.spec.postProcessor },
  model: createBpeModel({
    vocab: fixture.asset.vocab.map(([id, token]) => [id, token] as const),
    merges: fixture.asset.merges.map(([left, right, rank]) => [left, right, rank] as const),
    byteIds: fixture.asset.byteIds,
  }),
  addedTokens: new Map(fixture.asset.addedTokens),
  specialIds: new Set(fixture.asset.specialIds),
  unkId: fixture.asset.unkId,
  bosId: fixture.asset.bosId,
  eosId: fixture.asset.eosId,
};

const tokenizer = new IrodoriGemmaTokenizer(assets);

/** The plain path (this kind has no other). */
const PLAIN = { splitRareTokens: false } as const;

describe("v4-Large text tokenizer: the declaration and the ids Irodori adds", () => {
  it("the fixture's asset is the Gemma format with the bos-only post_processor", () => {
    assertEquals(fixture.spec.normalizer, "replace-space-with-metaspace");
    assertEquals(fixture.spec.preTokenizer, "split-space-merged-with-previous");
    assertEquals(fixture.spec.decoder, "metaspace-byte-fallback-fuse");
    assertEquals(fixture.spec.postProcessor, "bos");
  });

  it("BOS and pad are the ids upstream's wrapper uses (pad = the added token <pad>)", () => {
    assertEquals(tokenizer.bosId, fixture.conditioning.bosId);
    assertEquals(tokenizer.padId, fixture.conditioning.padId);
    // The two must differ, or the padding checks below could not tell them apart.
    assert(tokenizer.bosId !== tokenizer.padId);
  });

  it("has no rare-token split table", () => {
    assertEquals(tokenizer.hasRareTokenSplit, false);
  });
});

// ---- ① Encode cases: upstream normalize_text, then the plain encoding ----

describe("v4-Large encode parity: the same ids as upstream's tokenizer on the normalized text", () => {
  for (const testCase of fixture.encode.cases) {
    it(`${testCase.name} — ${testCase.why}`, () => {
      // Irodori's normalization runs before the Gemma tokenizer; the TS normalizer must give the
      // string upstream's tokenizer was measured on.
      assertEquals(normalizeText(testCase.raw), testCase.normalized, "the normalized string");
      assertEquals(tokenizer.encode(testCase.normalized, PLAIN), testCase.ids, "ids");
    });
  }
});

// ---- ② The final form of batch_encode (max_text_len, and max_caption_len for batch-caption) ----

describe("v4-Large assembly parity: BOS + body cut at max_length − 1 + right pad + mask", () => {
  for (const testCase of fixture.encode.batch) {
    it(`${testCase.name} — ${testCase.why}`, () => {
      const padded = encodePaddedIds(tokenizer, testCase.normalized, testCase.maxLength, PLAIN);
      assertEquals([...padded.ids], testCase.idsPadded, "idsPadded");
      assertEquals([...padded.mask], testCase.mask.map(Number), "mask");
      // The pipeline's text path from the raw text (normalize + strip + pack) gives the valid prefix.
      const used = testCase.mask.filter(Boolean).length;
      assertEquals(
        [...packIds(tokenizer, testCase.raw, testCase.maxLength, "text", PLAIN)],
        testCase.idsPadded.slice(0, used),
        "packed text path",
      );
    });
  }

  it("truncation really fires in one case, and a short case is padded with <pad>", () => {
    const truncated = fixture.encode.batch.find((entry) => entry.name === "batch-truncated");
    assert(truncated !== undefined, "the fixture has no truncation case");
    assert(
      tokenizer.encode(truncated.normalized, PLAIN).length + 1 > truncated.maxLength,
      "truncation did not fire",
    );
    assertEquals(truncated.mask.filter(Boolean).length, truncated.maxLength);
    const short = fixture.encode.batch.find((entry) => entry.name === "batch-short");
    assert(short !== undefined, "the fixture has no short case");
    const used = short.mask.filter(Boolean).length;
    assert(used < short.maxLength, "the short case is not padded");
    assertEquals(
      short.idsPadded.slice(used),
      Array(short.maxLength - used).fill(fixture.conditioning.padId),
    );
  });
});

// ---- ③ The caption path (strip only) and the text path (normalize) of the same raw text ----

describe("v4-Large caption parity: packed ids of both paths at max_caption_len", () => {
  for (const testCase of fixture.encode.caption) {
    it(`${testCase.name} — ${testCase.why}`, () => {
      assertEquals(
        [...packCaptionIds(tokenizer, testCase.raw, testCase.maxLength)],
        testCase.idsPacked,
        "caption path (strip only)",
      );
      assertEquals(
        [...packIds(tokenizer, testCase.raw, testCase.maxLength, "text", PLAIN)],
        testCase.normalizedIdsPacked,
        "text path (normalize + strip)",
      );
      assertEquals(testCase.raw.trim(), testCase.stripped, "the stripped string");
      assertEquals(
        normalizeText(testCase.raw).trim(),
        testCase.normalized,
        "the normalized string",
      );
    });
  }

  it("the long cases pin the caption window: one beyond max_text_len, one cut at max_caption_len", () => {
    // max_text_len is the length of the batch case that truncates the text.
    const textLength = fixture.encode.batch.find(
      (entry) => entry.name === "batch-truncated",
    )?.maxLength;
    assert(textLength !== undefined, "the fixture has no truncation case");
    const over = fixture.encode.caption.find((entry) => entry.name === "caption-over-text-length");
    const cut = fixture.encode.caption.find((entry) => entry.name === "caption-truncated");
    assert(over !== undefined && cut !== undefined, "the fixture lacks a long caption case");
    assert(
      over.idsPacked.length > textLength && over.idsPacked.length < over.maxLength,
      `caption-over-text-length has ${over.idsPacked.length} ids`,
    );
    assertEquals(cut.idsPacked.length, cut.maxLength);
    assert(
      tokenizer.encode(cut.stripped, PLAIN).length + 1 > cut.maxLength,
      "caption-truncated does not overflow max_caption_len",
    );
  });

  it("the two paths really differ on most cases (the check is not vacuous)", () => {
    const sensitive = fixture.encode.caption.filter((entry) => entry.normalizeSensitive);
    assert(sensitive.length >= fixture.encode.caption.length - 1);
    for (const entry of sensitive)
      assert(entry.idsPacked.join() !== entry.normalizedIdsPacked.join());
  });
});

// ---- ④ The rare-token split on this kind (absent) ----

describe("v4-Large rare-token split: the knob behaves as for an asset without the table", () => {
  it("an explicit split request on the tokenizer fails with the existing message", () => {
    assertThrows(
      () => tokenizer.encode("abc", { splitRareTokens: true }),
      Error,
      "carries no rareTokenSplit table",
    );
    assertThrows(
      () => encodePaddedIds(tokenizer, "abc", 8, { splitRareTokens: true }),
      Error,
      "carries no rareTokenSplit table",
    );
  });

  it("omitted resolves to off, false holds, true is an input error", () => {
    assertEquals(resolveSplitRareTokens(undefined, tokenizer), false);
    assertEquals(resolveSplitRareTokens(false, tokenizer), false);
    assertThrows(() => resolveSplitRareTokens(true, tokenizer), ModelInputError, "splitRareTokens");
  });

  it("an unpaired surrogate is an input error under Irodori's label", () => {
    assertThrows(() => tokenizer.encode("a\uD800", PLAIN), ModelInputError, "irodori text");
  });
});

// ---- ⑤ Choosing the tokenizer by the asset's format ----

/** Byte value → byte_fallback spelling (`<0x00>`..`<0xFF>`). */
const byteToken = (byte: number): string =>
  `<0x${byte.toString(16).toUpperCase().padStart(2, "0")}>`;
const BYTE_TOKENS: readonly string[] = Array.from({ length: 256 }, (_, byte) => byteToken(byte));

/** A minimal Gemma-format asset JSON (`<pad>` 0 / `<eos>` 1 / `<bos>` 2 / `<unk>` 3, as in T5Gemma 2). */
const gemmaAssetJson = (): Record<string, unknown> => {
  const vocab = ["<pad>", "<eos>", "<bos>", "<unk>", ...BYTE_TOKENS, "a", "aa"];
  return {
    format: "karume-gemma-tokenizer/1",
    spec: {
      normalizer: "replace-space-with-metaspace",
      preTokenizer: "split-space-merged-with-previous",
      decoder: "metaspace-byte-fallback-fuse",
      postProcessor: "bos",
    },
    vocab,
    mergesText: `${vocab.indexOf("a")} ${vocab.indexOf("a")}`,
    mergesCount: 1,
    byteIds: BYTE_TOKENS.map((token) => vocab.indexOf(token)),
    addedTokens: [
      ["<pad>", 0],
      ["<eos>", 1],
      ["<bos>", 2],
      ["<unk>", 3],
    ],
    specialIds: [0, 1, 2, 3],
    unkId: 3,
    bosId: 2,
    eosId: 1,
  };
};

/** A minimal Unigram asset JSON of the Small models (no `format` key). */
const unigramAssetJson = (): Record<string, unknown> => {
  const tokens = ["<unk>", "<s>", "<pad>", ...BYTE_TOKENS, "a"];
  return {
    vocabText: tokens.join("\n"),
    scores: tokens.map(() => 0),
    addedTokens: [
      ["<unk>", 0],
      ["<s>", 1],
      ["<pad>", 2],
    ],
    unkId: 0,
    byteBaseId: 3,
    bosId: 1,
    padId: 2,
  };
};

describe("tokenizer choice: the asset's format decides the kind", () => {
  it("an asset without a format key is the Unigram tokenizer of the Small models", () => {
    const chosen = parseIrodoriTextTokenizer(unigramAssetJson());
    assertInstanceOf(chosen, IrodoriTokenizer);
    assertEquals([chosen.bosId, chosen.padId], [1, 2]);
  });

  it("the Gemma format is the Gemma tokenizer, BOS from bosId and pad from <pad>", () => {
    const chosen = parseIrodoriTextTokenizer(gemmaAssetJson());
    assertInstanceOf(chosen, IrodoriGemmaTokenizer);
    assertEquals([chosen.bosId, chosen.padId, chosen.hasRareTokenSplit], [2, 0, false]);
    // Irodori's back end: BOS + body + <pad>, the post_processor not applied on top.
    const padded = encodePaddedIds(chosen, "aaa", 6, PLAIN);
    const body = chosen.encode("aaa", PLAIN);
    assertEquals([...padded.ids], [2, ...body, ...Array(5 - body.length).fill(0)]);
  });

  it("an unknown format fails loudly instead of being read as either kind", () => {
    for (const format of ["karume-gemma-tokenizer/2", "something-else", 1]) {
      assertThrows(
        () => parseIrodoriTextTokenizer({ ...gemmaAssetJson(), format }),
        Error,
        "unknown tokenizer asset format",
      );
    }
  });

  it("a Gemma asset without the added token <pad> fails (there is no padId field to fall back on)", () => {
    const asset = gemmaAssetJson();
    asset["addedTokens"] = [
      ["<eos>", 1],
      ["<bos>", 2],
      ["<unk>", 3],
    ];
    asset["specialIds"] = [1, 2, 3];
    assertThrows(() => parseIrodoriTextTokenizer(asset), Error, "<pad>");
  });

  it("the Gemma reader's own checks still apply behind the choice", () => {
    const asset = gemmaAssetJson();
    asset["spec"] = { ...(asset["spec"] as Record<string, unknown>), postProcessor: "eos" };
    assertThrows(() => parseIrodoriTextTokenizer(asset), Error, "postProcessor");
  });

  it("a non-object asset fails as before", () => {
    assertThrows(() => parseIrodoriTextTokenizer(undefined), Error, "not an object");
  });
});
